class Solution:
    def ambiguousCoordinates(self, s: str) -> List[str]:
        d = s[1:-1]
        n = len(d)

        def gen(sub):
            res = []
            for i in range(1, len(sub)):
                a, b = sub[:i], sub[i:]
                if (len(a) == 1 or a[0] != '0') and b[-1] != '0':
                    res.append(a + '.' + b)
            if sub == '0' or sub[0] != '0':
                res.append(sub)
            return res

        ans = []
        for k in range(1, n):
            for l in gen(d[:k]):
                for r in gen(d[k:]):
                    ans.append('(' + l + ', ' + r + ')')
        return ans

