            vector<string> res;
            for (int i = 1; i < (int)sub.size(); i++) {
                string a = sub.substr(0, i), b = sub.substr(i);
                if ((a.size() == 1 || a[0] != '0') && b.back() != '0')
                    res.push_back(a + "." + b);
