            if (sub == "0" || sub[0] != '0') res.push_back(sub);
            return res;
        };
        vector<string> ans;
        for (int k = 1; k < n; k++) {
            for (auto& l : gen(d.substr(0, k)))
                for (auto& r : gen(d.substr(k)))
                    ans.push_back("(" + l + ", " + r + ")");
