from functools import lru_cache

class Solution:
    def ambiguousCoordinates(self, s: str) -> List[str]:
        d = s[1:-1]
        n = len(d)

        @lru_cache(maxsize=None)
        def expand(i, j):
            sub = d[i:j]
            res = []
            for k in range(i + 1, j):
                a, b = d[i:k], d[k:j]
                if (len(a) == 1 or a[0] != '0') and b[-1] != '0':
                    res.append(a + '.' + b)
            if sub == '0' or sub[0] != '0':
                res.append(sub)
            return tuple(res)

        ans = []
        for k in range(1, n):
            for l in expand(0, k):
                for r in expand(k, n):
                    ans.append(f'({l}, {r})')
        return ans

