class Solution {
    private String d;
    private List<String>[][] memo;

    public List<String> ambiguousCoordinates(String s) {
        d = s.substring(1, s.length() - 1);
        int n = d.length();
        memo = new ArrayList[n + 1][n + 1];
        List<String> ans = new ArrayList<>();
        for (int k = 1; k < n; k++)
            for (String l : expand(0, k))
                for (String r : expand(k, n))
                    ans.add("(" + l + ", " + r + ")");
        return ans;
    }

    private List<String> expand(int i, int j) {
        if (memo[i][j] != null) return memo[i][j];
        List<String> res = new ArrayList<>();
        for (int k = i + 1; k < j; k++) {
            String a = d.substring(i, k), b = d.substring(k, j);
            if ((a.length() == 1 || a.charAt(0) != '0') && b.charAt(b.length() - 1) != '0')
                res.add(a + "." + b);
        }
        String sub = d.substring(i, j);
        if (sub.equals("0") || sub.charAt(0) != '0') res.add(sub);
        return memo[i][j] = res;
    }
}

